    static final OffsetDateTime NOW=OffsetDateTime.parse("2026-10-21T10:21:05+08:00");static final LocalDate DAY=NOW.toLocalDate(),PRIOR=DAY.minusDays(1);
    static class MutableClock extends Clock {Instant value=NOW.toInstant();public ZoneId getZone(){return TradingDatePolicy.ZONE;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return value;}}
    @TestConfiguration(proxyBeanMethods=false) static class TimeConfig {@Bean @Primary MutableClock trendClock(){return new MutableClock();}}
    static final String SCHEMA="stocksentinel_trend_"+UUID.randomUUID().toString().replace("-","");
    static Connection connection()throws Exception{return DriverManager.getConnection(System.getenv("STOCKSENTINEL_TEST_DB_URL"),System.getenv("STOCKSENTINEL_TEST_DB_USER"),System.getenv("STOCKSENTINEL_TEST_DB_PASSWORD"));}
    @DynamicPropertySource static void database(DynamicPropertyRegistry r)throws Exception{if(!SCHEMA.matches("stocksentinel_trend_[a-f0-9]{32}"))throw new IllegalStateException();try(var c=connection();var s=c.createStatement()){s.execute("CREATE SCHEMA \""+SCHEMA+"\"");}r.add("spring.datasource.url",()->System.getenv("STOCKSENTINEL_TEST_DB_URL")+"?currentSchema="+SCHEMA);r.add("spring.datasource.username",()->System.getenv("STOCKSENTINEL_TEST_DB_USER"));r.add("spring.datasource.password",()->System.getenv("STOCKSENTINEL_TEST_DB_PASSWORD"));r.add("spring.flyway.default-schema",()->SCHEMA);}
    @AfterAll static void cleanup()throws Exception{if(!SCHEMA.matches("stocksentinel_trend_[a-f0-9]{32}"))throw new IllegalStateException();try(var c=connection();var s=c.createStatement()){s.execute("DROP SCHEMA \""+SCHEMA+"\" CASCADE");}}
    @Autowired TrendService service;@Autowired TrendLedger ledger;@Autowired TrendMapper mapper;@Autowired JdbcTemplate db;@Autowired ObjectMapper json;@Autowired NotificationSettings bot;@Autowired MutableClock clock;@Autowired PositionService positions;@Autowired GroupAssistantTools tools;
    @Autowired TrendPublisher publisher;
