    @MockitoBean MarketMapper marketBars;
    String group(){return bot.destinationHash("test-group");}
    BigDecimal n(String s){return new BigDecimal(s);}
    JsonNode view(Object o){return json.valueToTree(o);}
    JsonNode metrics(LocalDate day){return json.valueToTree(Map.ofEntries(Map.entry("symbol","000731"),Map.entry("version","trend-ma-atr-sma-v1"),Map.entry("as_of",day.toString()),Map.entry("window_hash","a".repeat(64)),Map.entry("history_size",120),Map.entry("close","52"),Map.entry("raw_close","52"),Map.entry("previous_raw_close","51"),Map.entry("ma20","50"),Map.entry("ma60","48"),Map.entry("ma120","44"),Map.entry("ma60_change20","0.02"),Map.entry("raw_atr14","1.5"),Map.entry("raw_factor","1"),Map.entry("previous_twenty_high","51"),Map.entry("recent_twenty_high","53"),Map.entry("amount","60000000"),Map.entry("volume","1000000")));}
    JsonNode quote(String key,String price){var q=json.createObjectNode();q.put("key",key).put("symbol",key.substring(2)).put("name",key.equals("sh000300")?"沪深300":"四川美丰").put("price",price).put("previous_close",key.equals("sh000300")?"98":"52").put("volume","1000000").put("amount","60000000").put("limit_up","80").put("limit_down","20").put("quoted_at",clock.instant().atOffset(ZoneOffset.ofHours(8)).minusSeconds(10).toString());return q;}
    @BeforeEach void seed()throws Exception{
        org.springframework.test.util.ReflectionTestUtils.setField(service,"scanNanos",(java.util.function.LongSupplier)System::nanoTime);
        clock.value=NOW.toInstant();db.execute("TRUNCATE chip_scan_run,scan_quote_state,scan_retry_request,stock_info,market_calendar,trend_follow_index,trend_follow_runtime,trend_follow_account,trend_follow_notice CASCADE");
        for(var d:List.of(PRIOR,DAY,DAY.plusDays(1)))db.update("INSERT INTO market_calendar(trade_date,exchange,is_open,source) VALUES(?,'CN',true,'TEST')",d);
        db.update("INSERT INTO stock_info(symbol,name,exchange) VALUES('000731','四川美丰','SZ')");mapper.seed(PRIOR);mapper.item(PRIOR,"000731","READY",null,metrics(PRIOR).toString());mapper.storeIndex(PRIOR,"{\"key\":\"sh000300\",\"as_of\":\""+PRIOR+"\",\"close\":100,\"ma200\":90}");
        reset(client,collection);when(client.quotes(anyList())).thenAnswer(call->{List<String> keys=call.getArgument(0);var result=json.createObjectNode();result.put("source","TENCENT_TREND_QUOTES").put("observed_at",clock.instant().atOffset(ZoneOffset.ofHours(8)).toString());var qs=result.putArray("quotes");for(String key:keys)qs.add(quote(key,key.equals("sh000300")?"100":"54"));result.putArray("failed_symbols");return result;});
        reset(chipClient);when(chipClient.snapshot(anyString(),any(),anyBoolean())).thenAnswer(call->ChipRulesTest.snapshot(call.getArgument(0),call.getArgument(1),clock.instant().atOffset(ZoneOffset.ofHours(8))));
    }
    long buy(String message){return view(ledger.buy(group(),"u1","000731",100,n("50"),message)).at("/lot/id").asLong();}
    JsonNode indexSnapshot(LocalDate day,String source,String close){return json.valueToTree(Map.of("key","sh000300","source",source,"as_of",day.toString(),"close",close,"ma200","90","previous_ma200","89","history_size",201));}
    @Test void historicalBackupRecoversAndIsReusedWithoutRepeatedCalls(){
        db.update("DELETE FROM trend_follow_index");mapper.saveRuntime("index-error:"+PRIOR,"{\"code\":\"TREND_INDEX_UNAVAILABLE\"}");when(client.index(PRIOR,false)).thenReturn(indexSnapshot(PRIOR,"TREND_CSI300_TENCENT","100"));
        service.prepare(PRIOR,false);service.prepare(PRIOR,false);
        assertEquals("TREND_CSI300_TENCENT",view(service.status()).at("/index/source").asText());assertEquals("ALLOW",view(service.status()).path("marketFilter").asText());assertTrue(view(service.status()).path("indexError").isNull());assertTrue(mapper.runtime("index-error:"+PRIOR).contains("RECOVERED"));verify(client,times(1)).index(PRIOR,false);
    }
    @Test void missingIndexAndWeakMarketHaveDistinctStatusesAndMessages(){
        db.update("DELETE FROM trend_follow_index");when(client.index(PRIOR,false)).thenThrow(new IllegalStateException("TREND_INDEX_UNAVAILABLE"));service.prepare(PRIOR,false);service.prepare(PRIOR,false);verify(client,times(1)).index(PRIOR,false);
        assertEquals("PAUSE_DATA_UNAVAILABLE",view(service.status()).path("marketFilter").asText());assertEquals("TREND_INDEX_UNAVAILABLE",view(service.status()).at("/indexError/code").asText());service.scan(false);assertEquals(2,db.queryForObject("SELECT count(*) FROM trend_follow_notice WHERE payload LIKE '%大盘数据缺失%'",Integer.class));
        mapper.storeIndex(PRIOR,indexSnapshot(PRIOR,"TREND_CSI300_TENCENT","80").toString());assertEquals("PAUSE_MARKET_WEAK",view(service.status()).path("marketFilter").asText());service.scan(false);assertEquals(2,db.queryForObject("SELECT count(*) FROM trend_follow_notice WHERE payload LIKE '%大盘偏弱%'",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM trend_follow_event",Integer.class));
    }
    @Test void todayConfirmationOfOtherSourceCannotAuthorizeTencentFallback(){
        clock.value=NOW.withHour(15).withMinute(20).toInstant();db.update("INSERT INTO market_close_confirmation(trade_date,source) VALUES(?,'TREND_CSI300_EASTMONEY')",DAY);when(client.index(DAY,true,"EASTMONEY")).thenReturn(indexSnapshot(DAY,"TREND_CSI300_TENCENT","100"));service.prepare(DAY,false);
        assertNull(mapper.index(DAY));assertTrue(mapper.runtime("index-error:"+DAY).contains("TREND_INDEX_UNAVAILABLE"));verify(client).index(DAY,true,"EASTMONEY");verify(client,never()).index(DAY,true);
    }
