        db.update("DELETE FROM trend_follow_index");when(client.index(PRIOR,false)).thenReturn(indexSnapshot(PRIOR,"UNTRUSTED_SOURCE","100"));service.prepare(PRIOR,false);assertNull(mapper.index(PRIOR));assertEquals("PAUSE_DATA_UNAVAILABLE",view(service.status()).path("marketFilter").asText());
