    @Test void preparationUsesSameOverlappingWindowWithoutDroppingInternalGaps(){
        var raw=new ArrayList<com.stocksentinel.common.entity.MarketDailyBar>();var adjusted=new ArrayList<com.stocksentinel.common.entity.MarketDailyBar>();
        for(int i=0;i<121;i++){var b=new com.stocksentinel.common.entity.MarketDailyBar();b.symbol="000731";b.tradeDate=PRIOR.minusDays(120-i);b.openPrice=n("52");b.highPrice=n("53");b.lowPrice=n("51");b.closePrice=n("52");b.volume=n("10000");b.amount=n("60000000");b.source="TEST";adjusted.add(b);if(i>0)raw.add(b);}
        when(marketBars.daily(eq("000731"),any(),eq(PRIOR),eq(com.stocksentinel.market.MarketContracts.Adjustment.NONE))).thenReturn(raw);
        when(marketBars.daily(eq("000731"),any(),eq(PRIOR),eq(com.stocksentinel.market.MarketContracts.Adjustment.QFQ))).thenReturn(adjusted);
        when(client.calculate(eq("000731"),anyList(),anyList(),eq(false))).thenReturn(metrics(PRIOR));mapper.item(PRIOR,"000731","PENDING",null,null);
        service.prepare(PRIOR,false);
        verify(client).calculate(eq("000731"),argThat(b->b.size()==120&&b.getFirst().tradeDate().equals(PRIOR.minusDays(119))),argThat(b->b.size()==120&&b.getFirst().tradeDate().equals(PRIOR.minusDays(119))),eq(false));
        assertNotNull(mapper.metrics("000731",PRIOR));verifyNoInteractions(collection);
    }
    @Test void buyIsIdempotentAndUsesPreEntryAtr(){long id=buy("buy1");assertEquals("DUPLICATE",view(ledger.buy(group(),"u1","000731",100,n("50"),"buy1")).path("status").asText());var lot=mapper.lot(id,group(),"u1");assertEquals(0,n("47").compareTo(lot.stopPrice));assertEquals(PRIOR,lot.stopAsOf);assertEquals(100,db.queryForObject("SELECT quantity FROM personal_position",Long.class));assertEquals(0,db.queryForObject("SELECT sellable_quantity FROM personal_position",Long.class));}
