    void oneBatchBudget(){var ticks=new java.util.concurrent.atomic.AtomicInteger();org.springframework.test.util.ReflectionTestUtils.setField(service,"scanNanos",(java.util.function.LongSupplier)()->ticks.getAndIncrement()<2?0L:46_000_000_000L);}
    com.stocksentinel.monitoring.ScanRecoveryService.Request retryRequest(String id){return new com.stocksentinel.monitoring.ScanRecoveryService.Request(com.stocksentinel.monitoring.ScanRecoveryService.Pipeline.TREND_HISTORY,PRIOR,List.of("000731"),id,false);}
    @Test void failedBatchAdvancesCursorAndDoesNotStarveRestOfUniverse(){
        extraStocks(205);when(client.quotes(anyList())).thenThrow(new IllegalStateException("safe fixture"));
        oneBatchBudget();var first=view(service.scan(false)).path("quoteCycle");String cursor=mapper.runtime("quote-cursor");assertEquals(100,first.path("attempted").asInt());assertEquals("RUNNING",first.path("status").asText());
        oneBatchBudget();var second=view(service.scan(false)).path("quoteCycle");assertNotEquals(cursor,mapper.runtime("quote-cursor"));assertEquals(199,second.path("attempted").asInt());
        oneBatchBudget();var last=view(service.scan(false)).path("quoteCycle");assertTrue(last.path("attemptCoverageComplete").asBoolean());assertFalse(last.path("allQuotesValid").asBoolean());assertEquals(207,last.path("attempted").asInt());assertEquals("PARTIAL",last.path("status").asText());
        assertEquals(0,db.queryForObject("SELECT count(*) FROM scan_quote_state WHERE last_success_at IS NOT NULL",Integer.class));assertEquals(0,db.queryForObject("SELECT count(*) FROM trend_follow_event",Integer.class));
    }
