    @Test void cycleResumesFromPersistentStateAndSeparatesUniverseAndPhase(){
        var keys=List.of("sh000300","sz000731");var a=coverage.begin(DAY,"PREVIEW",keys);coverage.record(a,List.of(new com.stocksentinel.monitoring.ScanCoverageMapper.Quote("sh000300","FAILED","QUOTE_SOURCE_UNAVAILABLE",false,null)),null);var partial=coverage.finish(a);assertEquals(1,partial.path("attempted").asInt());
        var resumed=coverage.begin(DAY,"PREVIEW",keys);assertEquals(a.path("id"),resumed.path("id"));assertEquals(Set.of("sh000300"),coverage.covered(resumed));
        var expanded=coverage.begin(DAY,"PREVIEW",List.of("sh000300","sz000731","sz000001"));assertNotEquals(a.path("id"),expanded.path("id"));assertTrue(mapper.runtime("quote-cycle-last").contains("SUPERSEDED"));var closed=coverage.begin(DAY,"CONFIRMED",keys);assertNotEquals(expanded.path("id"),closed.path("id"));assertTrue(coverage.covered(closed).isEmpty());
    }
